'use strict';

// MODULES //

var exp = require( '@stdlib/math/base/special/exp' );
var absf = require( '@stdlib/math/base/special/absf' );
var toWordf = require( '@stdlib/number/float32/base/to-word' );
var fromWordf = require( '@stdlib/number/float32/base/from-word' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// VARIABLES //

var TINY = f32( 1.0e-30 );
var HALF = f32( 0.5 );
var ONE = f32( 1.0 );
var TWO = f32( 2.0 );

// 0x3f57bb00
var ERX = f32( 8.42697144e-01 );

// Polynomial coefficients for domain [0, 0.84375]:
var PP0 = f32( 1.28379166e-01 );  // 0x3e0375d4
var PP1 = f32( -3.36030394e-01 ); // 0xbeac0c2d
var PP2 = f32( -1.86261395e-03 ); // 0xbaf422f4
var QQ1 = f32( 3.12324315e-01 );  // 0x3e9fe8f9
var QQ2 = f32( 2.16070414e-02 );  // 0x3cb10140
var QQ3 = f32( -1.98859372e-03 ); // 0xbb025311

// Polynomial coefficients for domain [0.84375, 1.25]:
var PA0 = f32( 3.65041046e-06 );  // 0x3674f993
var PA1 = f32( 4.15109307e-01 );  // 0x3ed48935
var PA2 = f32( -2.09395722e-01 ); // 0xbe566bd5
var PA3 = f32( 8.67677554e-02 );  // 0x3db1b34b
var QA1 = f32( 4.95560974e-01 );  // 0x3efdba2b
var QA2 = f32( 3.71248513e-01 );  // 0x3ebe1449
var QA3 = f32( 3.92478965e-02 );  // 0x3d20c267

// Polynomial coefficients for domain [1.25, 1/0.35]:
var RA0 = f32( -9.88156721e-03 ); // 0xbc21e64c
var RA1 = f32( -5.43658376e-01 ); // 0xbf0b2d32
var RA2 = f32( -1.66828310e+00 ); // 0xbfd58a4d
var RA3 = f32( -6.91554189e-01 ); // 0xbf3109b2
var SA1 = f32( 4.48581553e+00 );  // 0x408f8bcd
var SA2 = f32( 4.10799170e+00 );  // 0x408374ab
var SA3 = f32( 5.53855181e-01 );  // 0x3f0dc974

// Polynomial coefficients for domain [2.85715, 11]:
var RB0 = f32( -9.86496918e-03 ); // 0xbc21a0ae
var RB1 = f32( -5.48049808e-01 ); // 0xbf0c4cfe
var RB2 = f32( -1.84115684e+00 ); // 0xbfebab07
var SB1 = f32( 4.87132740e+00 );  // 0x409be1ea
var SB2 = f32( 3.04982710e+00 );  // 0x4043305e
var SB3 = f32( -7.61900663e-01 ); // 0xbf430bec


// MAIN //

/**
* Evaluates the complementary error function for a single-precision floating-point number.
*
* ## Method
*
* 1.  For \\( x \in [0, 0.84375] \\), we use the approximation
*
*     ```tex
*     \operatorname{erfc}(x) = 1 - \operatorname{erf}(x) = 1 - x \cdot \frac{P(x^2)}{Q(x^2)}
*     ```
*
*     where \\( P \\) and \\( Q \\) are polynomials (pp and qq).
*
* 2.  For \\( x \in [0.84375, 1.25] \\), we use the approximation
*
*     ```tex
*     \operatorname{erfc}(x) = 1 - \operatorname{erf}(x) = 1 - \operatorname{erx} - \frac{P(x-1)}{Q(x-1)}
*     ```
*
*     where \\( P \\) and \\( Q \\) are polynomials (pa and qa).
*
* 3.  For \\( x \in [1.25, 11] \\), we use the approximation
*
*     ```tex
*     \operatorname{erfc}(x) = \frac{1}{x} e^{-x^2 - 0.5625 + \frac{R(1/x^2)}{S(1/x^2)}}
*     ```
*
*     where \\( R \\) and \\( S \\) are rational functions (ra/sa for x < 2.85715, rb/sb for x >= 2.85715).
*
* 4.  For \\( x \geq 11 \\), we use the approximation
*
*     ```tex
*     \operatorname{erfc}(x) = 0
*     ```
*
* ## Notes
*
* -   Relative error:
*     - \\( |x| < 0.84375 \\): \\( 2^{-31} \\)
*     - \\( 0.84375 \leq |x| < 1.25 \\): \\( 2^{-31} \\)
*     - \\( 1.25 \leq |x| < 2.85715 \\): \\( 2^{-30} \\)
*     - \\( 2.85715 \leq |x| < 11 \\): \\( 2^{-30} \\)
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var y = erfcf( 0.0 );
* // returns 1.0
*
* @example
* var y = erfcf( 1.0 );
* // returns ~0.1573
*
* @example
* var y = erfcf( -1.0 );
* // returns ~1.8427
*
* @example
* var y = erfcf( Infinity );
* // returns 0.0
*
* @example
* var y = erfcf( -Infinity );
* // returns 2.0
*
* @example
* var y = erfcf( NaN );
* // returns NaN
*/
function erfcf( x ) {
    var hx;
    var ix;
    var R;
    var S;
    var P;
    var Q;
    var s;
    var y;
    var z;
    var r;
    var ax;
    var xm2;

    x = f32( x );
    hx = toWordf( x ) | 0; // asm type annotation
    ix = (hx & 0x7fffffff) | 0; // asm type annotation

    // Case: |x| < 0.84375
    if ( ix < 0x3f580000 ) {
        // Case: |x| < 2**-24
        if ( ix < 0x33800000 ) {
            return f32( ONE - x );
        }
        z = f32( x * x );
        r = f32( PP0 + f32( z * f32( PP1 + f32( z * PP2 ) ) ) );
        s = f32( ONE + f32( z * f32( QQ1 + f32( z * f32( QQ2 + f32( z * QQ3 ) ) ) ) ) );
        y = f32( r / s );
        if ( hx < 0x3e800000 ) {
            // Case: x < 1/4
            return f32( ONE - f32( x + f32( x * y ) ) );
        }
        r = f32( x * y );
        r = f32( r + f32( x - HALF ) );
        return f32( HALF - r );
    }
    // Case: 0.84375 <= |x| < 1.25
    if ( ix < 0x3fa00000 ) {
        ax = absf( x );
        s = f32( f32( ax ) - ONE );
        P = f32( PA0 + f32( s * f32( PA1 + f32( s * f32( PA2 + f32( s * PA3 ) ) ) ) ) );
        Q = f32( ONE + f32( s * f32( QA1 + f32( s * f32( QA2 + f32( s * QA3 ) ) ) ) ) );
        if ( hx >= 0 ) {
            z = f32( ONE - ERX );
            return f32( z - f32( P / Q ) );
        }
        z = f32( ERX + f32( P / Q ) );
        return f32( ONE + z );
    }
    // Case: |x| < 11
    if ( ix < 0x41300000 ) {
        ax = abs( x );
        ax = f32( ax );
        s = f32( ONE / f32( ax * ax ) );

        // Case: |x| < 2.85715 ~ 1/0.35
        if ( ix < 0x4036db8c ) {
            R = f32( RA0 + f32( s * f32( RA1 + f32( s * f32( RA2 + f32( s * RA3 ) ) ) ) ) );
            S = f32( ONE + f32( s * f32( SA1 + f32( s * f32( SA2 + f32( s * SA3 ) ) ) ) ) );
        } else {
            // Case: x < -5
            if ( hx < 0 && ix >= 0x40a00000 ) {
                return f32( TWO - TINY );
            }
            R = f32( RB0 + f32( s * f32( RB1 + f32( s * RB2 ) ) ) );
            S = f32( ONE + f32( s * f32( SB1 + f32( s * f32( SB2 + f32( s * SB3 ) ) ) ) ) );
        }
        z = f32( fromWordf( (hx & 0xffffe000) >>> 0 ) );
        xm2 = f32( f32( z - ax ) * f32( z + ax ) );
        r = f32( exp( f32( f32( f32( -z * z ) - f32( 0.5625 ) ) + f32( xm2 + f32( R / S ) ) ) ) );
        if ( hx > 0 ) {
            return f32( r / ax );
        }
        return f32( TWO - f32( r / ax ) );
    }
    // Case: |x| >= 11
    if ( hx > 0 ) {
        return f32( TINY * TINY );
    }
    return f32( TWO - TINY );
}


// EXPORTS //

module.exports = erfcf;